import React, { useState } from 'react';

const MEAL_SLOTS = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

const NUTRIENT_GOALS = {
  calories: 2000, protein: 50, carbs: 260, fat: 65, fiber: 25, sugar: 50, salt: 6,
};

const NUTRIENT_COLORS = {
  calories: '#A0856C', protein: '#7A8FA6', carbs: '#C4A035', fat: '#B85C5C', fiber: '#7A9E87', sugar: '#9B7AB8', salt: '#7A9E87',
};

function getWeekDates(referenceDate) {
    const today = referenceDate || new Date();
    const day = today.getDay();
    const monday = new Date(today);
    monday.setDate(today.getDate() - ((day + 6) % 7));
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return d.toISOString().split('T')[0];
    });
  }

function calcMealNutrition(meal) {
  if (!meal || !meal.ingredients) return { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 };
  const totals = meal.ingredients.reduce((acc, ing) => {
    const factor = (parseFloat(ing.amount) || 0) / 100;
    Object.keys(acc).forEach(k => { acc[k] += (ing.per100g[k] || 0) * factor; });
    return acc;
  }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 });
  const srv = meal.servings || 1;
  Object.keys(totals).forEach(k => { totals[k] = Math.round(totals[k] / srv * 10) / 10; });
  return totals;
}

function NutritionOverview({ planner }) {
  const [view, setView] = useState('day');
  const [selectedDay, setSelectedDay] = useState(() => (new Date().getDay() + 6) % 7);
  const [goals, setGoals] = useState(NUTRIENT_GOALS);
  const [showGoalModal, setShowGoalModal] = useState(false);
  const [goalForm, setGoalForm] = useState(NUTRIENT_GOALS);
  const weekDates = getWeekDates(new Date());

  function getDayNutrition(dayIndex) {
    return MEAL_SLOTS.reduce((totals, slot) => {
      const dateStr = weekDates[dayIndex];
      const key = `${dateStr}_${slot}`;
      const meal = planner[key];
      if (!meal) {
        // Also try without time component
        const altKey = Object.keys(planner).find(k => k.startsWith(dateStr) && k.endsWith(slot));
        if (!altKey) return totals;
      }
      const foundMeal = planner[key] || planner[Object.keys(planner).find(k => k.startsWith(dateStr) && k.endsWith(slot))];
      if (!foundMeal) return totals;
      const n = calcMealNutrition(foundMeal);
      Object.keys(totals).forEach(k => { totals[k] += n[k] || 0; });
      return totals;
    }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 });
  }

  function getWeekNutrition() {
    return Array.from({ length: 7 }, (_, i) => getDayNutrition(i)).reduce((totals, day) => {
      Object.keys(totals).forEach(k => { totals[k] += day[k]; });
      return totals;
    }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 });
  }

  const nutrition = view === 'day' ? getDayNutrition(selectedDay) : getWeekNutrition();
  const multiplier = view === 'week' ? 7 : 1;

  const units = { calories: 'kcal', protein: 'g', carbs: 'g', fat: 'g', fiber: 'g', sugar: 'g', salt: 'g' };

  return (
    <div>
      {/* View toggle */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
        {['day', 'week'].map(v => (
          <button key={v} onClick={() => setView(v)} style={{
            padding: '6px 16px', borderRadius: '20px', border: '1px solid',
            borderColor: view === v ? 'var(--accent)' : 'var(--border)',
            backgroundColor: view === v ? 'var(--accent)' : 'transparent',
            color: view === v ? 'var(--white)' : 'var(--text-secondary)',
            fontFamily: 'Jost, sans-serif', fontSize: '12px', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{v}</button>
        ))}
        <button onClick={() => { setGoalForm(goals); setShowGoalModal(true); }} style={{
          marginLeft: 'auto', padding: '6px 14px', borderRadius: '20px',
          border: '1px solid var(--border)', backgroundColor: 'transparent',
          color: 'var(--text-secondary)', fontFamily: 'Jost, sans-serif',
          fontSize: '12px', cursor: 'pointer',
        }}>Set goals</button>
      </div>

      {/* Day selector — only shown in day view */}
      {view === 'day' && (
        <div style={{ display: 'flex', gap: '6px', overflowX: 'auto', paddingBottom: '4px', marginBottom: '20px' }}>
          {DAYS.map((day, i) => (
            <button key={day} onClick={() => setSelectedDay(i)} style={{
              flexShrink: 0, padding: '6px 10px', borderRadius: '10px', border: '1.5px solid',
              borderColor: selectedDay === i ? 'var(--accent)' : 'var(--border)',
              backgroundColor: selectedDay === i ? 'var(--accent)' : 'transparent',
              color: selectedDay === i ? 'var(--white)' : 'var(--text-secondary)',
              fontFamily: 'Jost, sans-serif', fontSize: '11px', fontWeight: '500', cursor: 'pointer',
            }}>{day.slice(0, 3)}</button>
          ))}
        </div>
      )}

      {/* Calories hero */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '20px', marginBottom: '16px', textAlign: 'center' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px' }}>
          {view === 'day' ? DAYS[selectedDay].toUpperCase() : 'THIS WEEK'} · CALORIES
        </p>
        <p style={{ fontSize: '48px', fontWeight: '300', color: 'var(--accent)', lineHeight: 1 }}>
          {Math.round(nutrition.calories)}
        </p>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '4px' }}>
          of {goals.calories * multiplier} kcal goal
        </p>
        <div style={{ height: '6px', backgroundColor: 'var(--surface)', borderRadius: '3px', marginTop: '12px' }}>
          <div style={{
            height: '100%', borderRadius: '3px', transition: 'width 0.3s',
            width: `${Math.min(100, (nutrition.calories / (goals.calories * multiplier)) * 100)}%`,
            backgroundColor: nutrition.calories > goals.calories * multiplier ? 'var(--danger)' : 'var(--accent)',
          }} />
        </div>
      </div>

      {/* Macros grid */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '16px' }}>
        {['protein', 'carbs', 'fat', 'fiber'].map(key => {
          const val = Math.round(nutrition[key] * 10) / 10;
          const goal = goals[key] * multiplier;
          const pct = Math.min(100, (val / goal) * 100);
          return (
            <div key={key} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                <span style={{ fontSize: '12px', color: 'var(--text-secondary)', textTransform: 'capitalize' }}>{key}</span>
                <span style={{ fontSize: '12px', fontWeight: '600', color: NUTRIENT_COLORS[key] }}>{val}{units[key]}</span>
              </div>
              <div style={{ height: '4px', backgroundColor: 'var(--surface)', borderRadius: '2px' }}>
                <div style={{ height: '100%', borderRadius: '2px', width: `${pct}%`, backgroundColor: NUTRIENT_COLORS[key], transition: 'width 0.3s' }} />
              </div>
              <p style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '4px' }}>goal: {goal}{units[key]}</p>
            </div>
          );
        })}
      </div>

      {/* Secondary nutrients */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>OTHER NUTRIENTS</p>
        {['sugar', 'salt'].map(key => {
          const val = Math.round(nutrition[key] * 10) / 10;
          const goal = goals[key] * multiplier;
          const pct = Math.min(100, (val / goal) * 100);
          const over = val > goal;
          return (
            <div key={key} style={{ marginBottom: '12px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                <span style={{ fontSize: '13px', textTransform: 'capitalize' }}>{key}</span>
                <span style={{ fontSize: '12px', color: over ? 'var(--danger)' : 'var(--text-secondary)' }}>
                  {val}{units[key]} / {goal}{units[key]}
                </span>
              </div>
              <div style={{ height: '4px', backgroundColor: 'var(--surface)', borderRadius: '2px' }}>
                <div style={{ height: '100%', borderRadius: '2px', width: `${pct}%`, backgroundColor: over ? 'var(--danger)' : NUTRIENT_COLORS[key], transition: 'width 0.3s' }} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Goal modal */}
      {showGoalModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '85vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '20px', fontSize: '18px' }}>Daily Nutrition Goals</h3>
            {Object.keys(goals).map(key => (
              <div key={key} style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '6px', fontWeight: '500', textTransform: 'uppercase' }}>
                  {key} ({units[key]})
                </label>
                <input
                  type="number"
                  value={goalForm[key]}
                  onChange={e => setGoalForm({ ...goalForm, [key]: parseFloat(e.target.value) || 0 })}
                  style={{ width: '100%', padding: '10px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', outline: 'none' }}
                />
              </div>
            ))}
            <div style={{ display: 'flex', gap: '12px', marginTop: '8px' }}>
              <button onClick={() => setShowGoalModal(false)} style={{ flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' }}>Cancel</button>
              <button onClick={() => { setGoals(goalForm); setShowGoalModal(false); }} style={{ flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' }}>Save Goals</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default NutritionOverview;