function calcHours(start, end) {
  if (!start || !end) return 0;
  const [sh, sm] = start.split(':').map(Number);
  const [eh, em] = end.split(':').map(Number);
  const diff = (eh * 60 + em) - (sh * 60 + sm);
  return Math.max(0, diff / 60);
}

function formatHours(decimalHours) {
  const h = Math.floor(decimalHours);
  const m = Math.round((decimalHours - h) * 60);
  if (h === 0) return `${m}min`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}min`;
}

function formatDate(dateStr) {
  if (!dateStr) return '';
  return new Date(dateStr + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
}

function TranscriptionWidget({ transcript, onTranscriptChange }) {
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState(null);
  const recognitionRef = React.useRef(null);

  function startRecording() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setError('Speech recognition is not supported in this browser. Try Safari on iPhone.');
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'da-DK';
    recognition.continuous = true;
    recognition.interimResults = true;

    let finalTranscript = transcript || '';

    recognition.onresult = (event) => {
      let interimTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        if (result.isFinal) {
          finalTranscript += result[0].transcript + ' ';
        } else {
          interimTranscript += result[0].transcript;
        }
      }
      onTranscriptChange(finalTranscript + interimTranscript);
    };

    recognition.onerror = (event) => {
      setError(`Error: ${event.error}`);
      setIsRecording(false);
    };

    recognition.onend = () => {
      setIsRecording(false);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setIsRecording(true);
    setError(null);
  }

  function stopRecording() {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }
    setIsRecording(false);
  }

  return (
    <div>
      <textarea
        value={transcript}
        onChange={e => onTranscriptChange(e.target.value)}
        placeholder="Transcription will appear here as you speak. You can also type manually."
        rows={6}
        style={{ width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '13px', color: 'var(--text-primary)', marginBottom: '10px', outline: 'none', resize: 'none' }}
      />
      {error && <p style={{ fontSize: '12px', color: 'var(--danger)', marginBottom: '8px' }}>{error}</p>}
      <div style={{ display: 'flex', gap: '8px' }}>
        {isRecording ? (
          <button onClick={stopRecording} style={{
            flex: 1, padding: '10px', borderRadius: '10px', border: 'none',
            backgroundColor: 'var(--danger)', color: 'var(--white)',
            fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px',
          }}>
            <span style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: 'var(--white)', display: 'inline-block', animation: 'pulse 1s infinite' }} />
            Stop recording
          </button>
        ) : (
          <button onClick={startRecording} style={{
            flex: 1, padding: '10px', borderRadius: '10px', border: 'none',
            backgroundColor: 'var(--accent)', color: 'var(--white)',
            fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
          }}>🎙 Start recording in Danish</button>
        )}
        {transcript && (
          <button onClick={() => onTranscriptChange('')} style={{
            padding: '10px 14px', borderRadius: '10px', border: '1px solid var(--border)',
            backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif',
            fontSize: '13px', cursor: 'pointer', color: 'var(--text-secondary)',
          }}>Clear</button>
        )}
      </div>
    </div>
  );
}
