  async function parseAarshjul(file) {
    setAarshjulParsing(true);
    setAarshjulError('');
    setAarshjulSuggestions([]);
    try {
      const arrayBuffer = await new Promise((res, rej) => {
        const reader = new FileReader();
        reader.onload = () => res(reader.result);
        reader.onerror = rej;
        reader.readAsArrayBuffer(file);
      });

      const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let text = '';
      for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
        const page = await pdf.getPage(pageNum);
        const content = await page.getTextContent();
        const pageText = content.items.map(item => item.str).join(' ');
        text += pageText + '\n';
      }

      const ALWAYS_RELEVANT = [
        'salma', 'alle fk-medarbejdere', 'fk-medarbejdere', 'alle medarbejdere',
        'alt uv-personale', 'uv-medarbejdere', 'amr', 'med-møde', 'lokalmed',
        'personalemøde', 'teammøde', 'afdelingsmøde', 'personale-arrangement',
        'personaledag', 'julebrunch', 'førstehjælp', 'al personale',
      ];

      const MONTHS = {
        'januar': '01', 'februar': '02', 'marts': '03', 'april': '04',
        'maj': '05', 'juni': '06', 'juli': '07', 'august': '08',
        'september': '09', 'oktober': '10', 'november': '11', 'december': '12',
      };

      const lines = text.split(/[\n\r]+/).map(l => l.trim()).filter(Boolean);
      const suggestions = [];
      let currentYear = new Date().getFullYear();
      const yearMatch = text.match(/20(2[5-9]|3\d)/);
      if (yearMatch) currentYear = parseInt(yearMatch[0]);

      function parseDate(dayNum, monthNum) {
        const month = monthNum.padStart(2, '0');
        const day = dayNum.padStart(2, '0');
        const monthNumInt = parseInt(month);
        const year = monthNumInt >= 8 ? currentYear : currentYear + 1;
        return `${year}-${month}-${day}`;
      }

      function getReason(block) {
        const lower = block.toLowerCase();
        if (lower.includes('salma')) return 'Nævnt ved navn';
        if (lower.includes('amr')) return 'AMR';
        if (lower.includes('med-møde') || lower.includes('lokalmed')) return 'MED-møde';
        if (lower.includes('personalemøde')) return 'Personalemøde';
        if (lower.includes('teammøde')) return 'Teammøde';
        if (lower.includes('afdelingsmøde')) return 'Afdelingsmøde';
        if (lower.includes('julebrunch') || lower.includes('personaledag') || lower.includes('personale-arrangement')) return 'Alle medarbejdere';
        if (lower.includes('alle fk-medarbejdere') || lower.includes('fk-medarbejdere')) return 'Alle FK-medarbejdere';
        if (lower.includes('alt uv-personale') || lower.includes('uv-medarbejdere')) return 'Alle UV-medarbejdere';
        if (lower.includes('førstehjælp')) return 'Obligatorisk kursus';
        return 'Relevant begivenhed';
      }

      const datePattern = /^(man|tir|ons|tors|fre|lør|søn)[a-z]*\s+(\d{1,2})\/(\d{1,2})/i;
      const timePattern = /(\d{1,2})[.:](\d{2})\s*[-–]\s*(\d{1,2})[.:](\d{2})/;

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const dateMatch = line.match(datePattern);
        if (dateMatch) {
          const block = lines.slice(i, Math.min(i + 8, lines.length)).join(' ');
          const blockLower = block.toLowerCase();
          const isRelevant = ALWAYS_RELEVANT.some(kw => blockLower.includes(kw));
          if (isRelevant) {
            const dayNum = dateMatch[2];
            const monthNum = dateMatch[3];
            const dateStr = parseDate(dayNum, monthNum);
            const timeMatch = block.match(timePattern);
            const startTime = timeMatch ? `${timeMatch[1].padStart(2,'0')}:${timeMatch[2]}` : null;
            const endTime = timeMatch ? `${timeMatch[3].padStart(2,'0')}:${timeMatch[4]}` : null;
            const blockLines = lines.slice(i, Math.min(i + 5, lines.length));
            const titleLine = blockLines.find((l, idx) => idx > 0 && l.length > 5 && !l.match(datePattern)) || blockLines[0];
            suggestions.push({
              title: titleLine.slice(0, 80),
              date: dateStr,
              endDate: null,
              time: startTime,
              endTime: endTime,
              description: block.slice(0, 200),
              reason: getReason(block),
            });
          }
        }
      }

      if (suggestions.length === 0) {
        setAarshjulError('No relevant events found. The PDF may not contain readable text.');
      } else {
        setAarshjulSuggestions(suggestions.map((e, idx) => ({ ...e, _id: Date.now() + idx })));
      }
    } catch (e) {
      setAarshjulError(`Could not read the document: ${e.message}`);
    }
    setAarshjulParsing(false);
  }
