import React, { useState } from 'react';

const CATEGORIES = {
  'Tops': ['T-shirt', 'Blouse', 'Shirt', 'Tank top', 'Knit/Sweater', 'Hoodie', 'Crop top'],
  'Bottoms': ['Pants', 'Jeans', 'Skirt', 'Shorts', 'Leggings'],
  'Dresses & Jumpsuits': ['Dress', 'Jumpsuit', 'Playsuit'],
  'Outerwear': ['Jacket', 'Coat', 'Blazer', 'Vest'],
  'Shoes': ['Sneakers', 'Heels', 'Boots', 'Sandals', 'Flats', 'Loafers'],
  'Bags': ['Handbag', 'Tote', 'Backpack', 'Clutch', 'Crossbody'],
  'Accessories': ['Jewellery', 'Belt', 'Scarf', 'Hat', 'Sunglasses', 'Watch'],
  'Underwear & Loungewear': ['Bra', 'Underwear', 'Lounge set', 'Socks', 'Tights'],
  'Sleepwear': ['Pyjamas', 'Nightgown', 'Robe'],
  'Sportswear': ['Sports top', 'Sports leggings', 'Sports bra', 'Shorts'],
  'Shapewear': ['Shapewear'],
};

const STYLES = ['Casual', 'Formal', 'Party', 'Beach', 'Sport', 'Work', 'Cosy'];
const SEASONS = ['Spring', 'Summer', 'Autumn', 'Winter', 'All seasons'];
const COLORS = ['#2C2C2C', '#7A7370', '#F5F0EB', '#A0856C', '#7A9E87', '#7A8FA6', '#B85C5C', '#9B7AB8', '#C4A035', '#FFFFFF'];
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

const emptyForm = {
    name: '', category: 'Tops', subcategory: 'T-shirt',
    color: '#2C2C2C', style: 'Casual', season: 'All seasons',
    brand: '', notes: '', favorite: false, photo: null,
  };

const emptyInspo = { title: '', notes: '', style: 'Casual', season: 'All seasons' };

function getTodayIndex() { return (new Date().getDay() + 6) % 7; }

function Outfit({ wardrobe, setWardrobe, outfitPlanner: planner, setOutfitPlanner: setPlanner }) {
    const [activeTab, setActiveTab] = useState('wardrobe');
    const [inspiration, setInspiration] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [showInspoModal, setShowInspoModal] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [inspoForm, setInspoForm] = useState(emptyInspo);
  const [editingId, setEditingId] = useState(null);
  const [filterCategory, setFilterCategory] = useState('All');
  const [filterStyle, setFilterStyle] = useState('All');
  const [filterSeason, setFilterSeason] = useState('All');
  const [selectedDay, setSelectedDay] = useState(getTodayIndex());
  const [showPicker, setShowPicker] = useState(null);

  const subcategories = CATEGORIES[form.category] || [];

  const filtered = wardrobe.filter(item => {
    const catMatch = filterCategory === 'All' || item.category === filterCategory;
    const styleMatch = filterStyle === 'All' || item.style === filterStyle;
    const seasonMatch = filterSeason === 'All' || item.season === filterSeason || item.season === 'All seasons';
    return catMatch && styleMatch && seasonMatch;
  });

  function openCreate() { setForm(emptyForm); setEditingId(null); setShowModal(true); }
  function openEdit(item) {
    setForm({ name: item.name, category: item.category, subcategory: item.subcategory, color: item.color, style: item.style, season: item.season, brand: item.brand || '', notes: item.notes || '', favorite: item.favorite || false });
    setEditingId(item.id); setShowModal(true);
  }

  function saveItem() {
    if (!form.name.trim()) return;
    if (editingId) {
      setWardrobe(wardrobe.map(i => i.id === editingId ? { ...i, ...form } : i));
    } else {
      setWardrobe([...wardrobe, { ...form, id: Date.now() }]);
    }
    setShowModal(false);
  }

  function deleteItem(id) { setWardrobe(wardrobe.filter(i => i.id !== id)); setShowDeleteConfirm(null); }
  function toggleFavorite(id) { setWardrobe(wardrobe.map(i => i.id === id ? { ...i, favorite: !i.favorite } : i)); }

  function getPlannerSlots(dayIndex) {
    return planner[dayIndex] || [];
  }

  function addToPlanner(dayIndex, item) {
    const current = getPlannerSlots(dayIndex);
    if (current.find(i => i.id === item.id)) return;
    setPlanner({ ...planner, [dayIndex]: [...current, item] });
    setShowPicker(null);
  }

  function removeFromPlanner(dayIndex, itemId) {
    setPlanner({ ...planner, [dayIndex]: getPlannerSlots(dayIndex).filter(i => i.id !== itemId) });
  }

  function saveInspo() {
    if (!inspoForm.title.trim()) return;
    setInspiration([...inspiration, { ...inspoForm, id: Date.now() }]);
    setShowInspoModal(false);
    setInspoForm(emptyInspo);
  }

  function deleteInspo(id) { setInspiration(inspiration.filter(i => i.id !== id)); }

  const TABS = [
    { id: 'wardrobe', label: 'Wardrobe' },
    { id: 'planner', label: 'Planner' },
    { id: 'inspiration', label: 'Inspiration' },
  ];

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>STYLE</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Outfit</h1>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px' }}>
        {TABS.map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id)} style={{
            padding: '6px 16px', borderRadius: '20px', border: '1px solid',
            borderColor: activeTab === tab.id ? 'var(--accent)' : 'var(--border)',
            backgroundColor: activeTab === tab.id ? 'var(--accent)' : 'transparent',
            color: activeTab === tab.id ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{tab.label}</button>
        ))}
      </div>

      {/* WARDROBE TAB */}
      {activeTab === 'wardrobe' && (
        <div>
          {/* Stats */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginBottom: '20px' }}>
            {[
              { label: 'Total items', value: wardrobe.length },
              { label: 'Favourites', value: wardrobe.filter(i => i.favorite).length },
              { label: 'Categories', value: new Set(wardrobe.map(i => i.category)).size },
            ].map(s => (
              <div key={s.label} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '12px', textAlign: 'center' }}>
                <p style={{ fontSize: '20px', fontWeight: '300', color: 'var(--accent)' }}>{s.value}</p>
                <p style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>{s.label.toUpperCase()}</p>
              </div>
            ))}
          </div>

          {/* Filters */}
          <div style={{ marginBottom: '12px', overflowX: 'auto' }}>
            <div style={{ display: 'flex', gap: '6px', paddingBottom: '4px' }}>
              {['All', ...Object.keys(CATEGORIES)].map(cat => (
                <button key={cat} onClick={() => setFilterCategory(cat)} style={{
                  flexShrink: 0, padding: '5px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: filterCategory === cat ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: filterCategory === cat ? 'var(--accent)' : 'transparent',
                  color: filterCategory === cat ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer', whiteSpace: 'nowrap',
                }}>{cat}</button>
              ))}
            </div>
          </div>

          <div style={{ display: 'flex', gap: '6px', marginBottom: '8px', overflowX: 'auto', paddingBottom: '4px' }}>
            {['All', ...STYLES].map(s => (
              <button key={s} onClick={() => setFilterStyle(s)} style={{
                flexShrink: 0, padding: '4px 10px', borderRadius: '20px', border: '1px solid',
                borderColor: filterStyle === s ? 'var(--text-primary)' : 'var(--border)',
                backgroundColor: filterStyle === s ? 'var(--text-primary)' : 'transparent',
                color: filterStyle === s ? 'var(--white)' : 'var(--text-secondary)',
                fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer', whiteSpace: 'nowrap',
              }}>{s}</button>
            ))}
          </div>

          <div style={{ display: 'flex', gap: '6px', marginBottom: '20px', overflowX: 'auto', paddingBottom: '4px' }}>
            {['All', ...SEASONS].map(s => (
              <button key={s} onClick={() => setFilterSeason(s)} style={{
                flexShrink: 0, padding: '4px 10px', borderRadius: '20px', border: '1px solid',
                borderColor: filterSeason === s ? 'var(--accent-light)' : 'var(--border)',
                backgroundColor: filterSeason === s ? 'var(--accent-light)' : 'transparent',
                color: filterSeason === s ? 'var(--white)' : 'var(--text-secondary)',
                fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer', whiteSpace: 'nowrap',
              }}>{s}</button>
            ))}
          </div>

          {/* Items list */}
          {filtered.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>◇</p>
              <p style={{ fontSize: '14px' }}>{wardrobe.length === 0 ? 'Your wardrobe is empty — add your first item' : 'No items match your filters'}</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {filtered.map(item => (
                <div key={item.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                  {/* Photo or color dot */}
                  {item.photo ? (
                    <img src={item.photo} alt={item.name} style={{ width: '44px', height: '44px', borderRadius: '8px', objectFit: 'cover', flexShrink: 0 }} />
                  ) : (
                    <div style={{ width: '32px', height: '32px', borderRadius: '50%', backgroundColor: item.color, border: '1px solid var(--border)', flexShrink: 0 }} />
                  )}
                  {/* Info */}
                  <div style={{ flex: 1 }} onClick={() => openEdit(item)}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '2px' }}>
                      <p style={{ fontSize: '14px', fontWeight: '500' }}>{item.name}</p>
                      {item.favorite && <span style={{ fontSize: '12px' }}>♥</span>}
                    </div>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                      {item.subcategory} · {item.style} · {item.season}
                    </p>
                    {item.brand && <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{item.brand}</p>}
                  </div>
                  {/* Actions */}
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <button onClick={() => toggleFavorite(item.id)} style={{ background: 'none', border: 'none', fontSize: '16px', cursor: 'pointer', color: item.favorite ? '#B85C5C' : 'var(--border)' }}>♥</button>
                    <button onClick={() => setShowDeleteConfirm(item.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* FAB */}
          <button onClick={openCreate} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)',
            fontSize: '26px', border: 'none', cursor: 'pointer',
            boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* PLANNER TAB */}
      {activeTab === 'planner' && (
        <div>
          {/* Day selector */}
          <div style={{ display: 'flex', gap: '6px', overflowX: 'auto', paddingBottom: '4px', marginBottom: '20px' }}>
            {DAYS.map((day, i) => (
              <button key={day} onClick={() => setSelectedDay(i)} style={{
                flexShrink: 0, padding: '8px 12px', borderRadius: '12px', border: '1.5px solid',
                borderColor: selectedDay === i ? 'var(--accent)' : 'var(--border)',
                backgroundColor: selectedDay === i ? 'var(--accent)' : 'transparent',
                color: selectedDay === i ? 'var(--white)' : 'var(--text-secondary)',
                fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
              }}>{day.slice(0, 3)}</button>
            ))}
          </div>

          <h3 style={{ fontSize: '18px', fontWeight: '400', marginBottom: '16px' }}>{DAYS[selectedDay]}</h3>

          {/* Planned items */}
          {getPlannerSlots(selectedDay).length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '16px' }}>No outfit planned yet</p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '16px' }}>
              {getPlannerSlots(selectedDay).map(item => (
                <div key={item.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '12px 16px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <div style={{ width: '28px', height: '28px', borderRadius: '50%', backgroundColor: item.color, border: '1px solid var(--border)', flexShrink: 0 }} />
                  <div style={{ flex: 1 }}>
                    <p style={{ fontSize: '14px', fontWeight: '500' }}>{item.name}</p>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{item.subcategory}</p>
                  </div>
                  <button onClick={() => removeFromPlanner(selectedDay, item.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
          )}

          <button onClick={() => setShowPicker(selectedDay)} style={{
            width: '100%', padding: '14px', borderRadius: '12px',
            border: '1.5px dashed var(--border)', backgroundColor: 'transparent',
            color: 'var(--text-secondary)', fontFamily: 'Jost, sans-serif',
            fontSize: '13px', cursor: 'pointer',
          }}>+ Add item to outfit</button>
        </div>
      )}

      {/* INSPIRATION TAB */}
      {activeTab === 'inspiration' && (
        <div>
          {inspiration.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>✦</p>
              <p style={{ fontSize: '14px' }}>No inspiration saved yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {inspiration.map(inspo => (
                <div key={inspo.id} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: '15px', fontWeight: '500', marginBottom: '4px' }}>{inspo.title}</p>
                      <div style={{ display: 'flex', gap: '6px', marginBottom: '8px' }}>
                        <span style={{ fontSize: '10px', padding: '2px 8px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>{inspo.style}</span>
                        <span style={{ fontSize: '10px', padding: '2px 8px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>{inspo.season}</span>
                      </div>
                      {inspo.notes && <p style={{ fontSize: '13px', color: 'var(--text-secondary)', lineHeight: '1.5' }}>{inspo.notes}</p>}
                    </div>
                    <button onClick={() => deleteInspo(inspo.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ))}
            </div>
          )}

          <button onClick={() => setShowInspoModal(true)} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)',
            fontSize: '26px', border: 'none', cursor: 'pointer',
            boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Remove item?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteItem(showDeleteConfirm)} style={deleteBtnStyle}>Remove</button>
            </div>
          </div>
        </div>
      )}

      {/* Wardrobe item picker for planner */}
      {showPicker !== null && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '70vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '20px', fontSize: '16px' }}>Add to {DAYS[showPicker]}'s outfit</h3>
            {wardrobe.length === 0 ? (
              <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', padding: '20px 0' }}>No items in wardrobe yet</p>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {wardrobe.map(item => (
                  <button key={item.id} onClick={() => addToPlanner(showPicker, item)} style={{
                    padding: '12px 16px', borderRadius: '12px', border: '1px solid var(--border)',
                    backgroundColor: 'var(--white)', textAlign: 'left', cursor: 'pointer',
                    fontFamily: 'Jost, sans-serif', display: 'flex', alignItems: 'center', gap: '12px',
                  }}>
                    <div style={{ width: '24px', height: '24px', borderRadius: '50%', backgroundColor: item.color, border: '1px solid var(--border)', flexShrink: 0 }} />
                    <div>
                      <p style={{ fontSize: '14px', fontWeight: '500', color: 'var(--text-primary)', marginBottom: '2px' }}>{item.name}</p>
                      <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{item.subcategory} · {item.style}</p>
                    </div>
                  </button>
                ))}
              </div>
            )}
            <button onClick={() => setShowPicker(null)} style={{ width: '100%', padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer', marginTop: '16px' }}>Cancel</button>
          </div>
        </div>
      )}

      {/* Add/Edit wardrobe item modal */}
      {showModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Item' : 'New Item'}</h3>

            {/* Photo */}
            <label style={labelStyle}>PHOTO</label>
            <div style={{ marginBottom: '20px' }}>
              {form.photo ? (
                <div style={{ position: 'relative', marginBottom: '8px' }}>
                  <img src={form.photo} alt="Item" style={{ width: '100%', height: '180px', objectFit: 'cover', borderRadius: '12px' }} />
                  <button onClick={() => setForm({ ...form, photo: null })} style={{
                    position: 'absolute', top: '8px', right: '8px',
                    width: '28px', height: '28px', borderRadius: '50%',
                    backgroundColor: 'rgba(0,0,0,0.5)', border: 'none',
                    color: 'var(--white)', fontSize: '14px', cursor: 'pointer',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                  }}>✕</button>
                </div>
              ) : (
                <label style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  gap: '8px', padding: '16px', borderRadius: '12px',
                  border: '1.5px dashed var(--border)', cursor: 'pointer',
                  color: 'var(--text-secondary)', fontSize: '13px',
                }}>
                  📷 Take or choose photo
                  <input type="file" accept="image/*" onChange={e => {
                    const file = e.target.files[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = ev => setForm({ ...form, photo: ev.target.result });
                    reader.readAsDataURL(file);
                  }} style={{ display: 'none' }} />
                </label>
              )}
            </div>

            <label style={labelStyle}>ITEM NAME</label>
            <input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="e.g. White linen blouse" style={inputStyle} />

            <label style={labelStyle}>CATEGORY</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {Object.keys(CATEGORIES).map(cat => (
                <button key={cat} onClick={() => setForm({ ...form, category: cat, subcategory: CATEGORIES[cat][0] })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: form.category === cat ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: form.category === cat ? 'var(--accent)' : 'transparent',
                  color: form.category === cat ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{cat}</button>
              ))}
            </div>

            <label style={labelStyle}>SUBCATEGORY</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {subcategories.map(sub => (
                <button key={sub} onClick={() => setForm({ ...form, subcategory: sub })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: form.subcategory === sub ? 'var(--text-primary)' : 'var(--border)',
                  backgroundColor: form.subcategory === sub ? 'var(--text-primary)' : 'transparent',
                  color: form.subcategory === sub ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{sub}</button>
              ))}
            </div>

            <label style={labelStyle}>COLOUR</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {COLORS.map(c => (
                <button key={c} onClick={() => setForm({ ...form, color: c })} style={{
                  width: '30px', height: '30px', borderRadius: '50%', backgroundColor: c,
                  border: form.color === c ? '3px solid var(--accent)' : '2px solid var(--border)',
                  cursor: 'pointer', outline: 'none',
                }} />
              ))}
            </div>

            <label style={labelStyle}>STYLE</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {STYLES.map(s => (
                <button key={s} onClick={() => setForm({ ...form, style: s })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: form.style === s ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: form.style === s ? 'var(--accent)' : 'transparent',
                  color: form.style === s ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{s}</button>
              ))}
            </div>

            <label style={labelStyle}>SEASON</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {SEASONS.map(s => (
                <button key={s} onClick={() => setForm({ ...form, season: s })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: form.season === s ? 'var(--accent-light)' : 'var(--border)',
                  backgroundColor: form.season === s ? 'var(--accent-light)' : 'transparent',
                  color: form.season === s ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{s}</button>
              ))}
            </div>

            <label style={labelStyle}>BRAND</label>
            <input value={form.brand} onChange={e => setForm({ ...form, brand: e.target.value })} placeholder="Optional" style={inputStyle} />

            <label style={labelStyle}>NOTES</label>
            <input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Optional" style={inputStyle} />

            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '28px' }}>
              <input type="checkbox" id="fav" checked={form.favorite} onChange={e => setForm({ ...form, favorite: e.target.checked })} />
              <label htmlFor="fav" style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>Mark as favourite ♥</label>
            </div>

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveItem} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Add Item'}</button>
            </div>
          </div>
        </div>
      )}

      {/* Inspiration modal */}
      {showInspoModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>New Inspiration</h3>

            <label style={labelStyle}>TITLE</label>
            <input value={inspoForm.title} onChange={e => setInspoForm({ ...inspoForm, title: e.target.value })} placeholder="e.g. Summer brunch look" style={inputStyle} />

            <label style={labelStyle}>STYLE</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {STYLES.map(s => (
                <button key={s} onClick={() => setInspoForm({ ...inspoForm, style: s })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: inspoForm.style === s ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: inspoForm.style === s ? 'var(--accent)' : 'transparent',
                  color: inspoForm.style === s ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{s}</button>
              ))}
            </div>

            <label style={labelStyle}>SEASON</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {SEASONS.map(s => (
                <button key={s} onClick={() => setInspoForm({ ...inspoForm, season: s })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: inspoForm.season === s ? 'var(--accent-light)' : 'var(--border)',
                  backgroundColor: inspoForm.season === s ? 'var(--accent-light)' : 'transparent',
                  color: inspoForm.season === s ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{s}</button>
              ))}
            </div>

            <label style={labelStyle}>NOTES</label>
            <textarea value={inspoForm.notes} onChange={e => setInspoForm({ ...inspoForm, notes: e.target.value })}
              placeholder="Describe the look, items to combine, where to wear it..." rows={4}
              style={{ ...inputStyle, resize: 'none' }} />

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowInspoModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveInspo} style={saveBtnStyle}>Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const saveBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default Outfit;